import pytest
import requests

@pytest.mark.parametrize("category, year, expected_status", [
    ("che", 2020, 200),
    ("eco", 2019, 200),
    ("lit", 2021, 200),
    ("phy", 1901, 200),
    ("med", 2022, 200),
    ("pea", 2023, 200),
    ("invalid", 2020, 400),
    ("che", 1800, 422),
    ("lit", 2050, 404),
])
def test_get_nobel_prize(api_client, category, year, expected_status):
    """Test the Nobel Prize endpoint with various categories and years."""
    endpoint = f"/2.1/nobelPrize/{category}/{year}"
    response = api_client.get(endpoint)
    assert response.status_code == expected_status

    if response.status_code == 200:
        data = response.json()
        assert "nobelPrize" in data
        assert data["nobelPrize"]["awardYear"] == year
        assert data["nobelPrize"]["category"]["en"] in ["Chemistry", "Economics", "Literature", "Peace", "Physics", "Medicine"]

    elif response.status_code in [400, 404, 422]:
        error_data = response.json()
        assert "code" in error_data
        assert "message" in error_data

def test_missing_authentication(api_client):
    """Test the endpoint without authentication."""
    endpoint = "/2.1/nobelPrize/che/2020"
    response = api_client.get(endpoint, headers={})
    assert response.status_code in [401, 403]

def test_invalid_authentication(api_client, invalid_api_key):
    """Test the endpoint with invalid authentication."""
    endpoint = "/2.1/nobelPrize/che/2020"
    headers = {"Authorization": f"Bearer {invalid_api_key}"}
    response = api_client.get(endpoint, headers=headers)
    assert response.status_code in [401, 403]
